using System.Numerics;
using Vortice.Mathematics;

namespace YMM4EffectShapes;

// =====================================================================
//  図形 ピクトグラム(Q6Art の種類 64)。案内の絵記号をオリジナルで描く(実在の規格の絵はまねない)
//  絵は「部品の並び」(円・四角・太い線・多角形・輪・文字)で作り、2D と専用3Dモデルの両方で同じ形にする
//  形: 0=案内(青) 1=安全(緑) 2=禁止(白地に赤い輪と斜線) 3=注意(黄) 4=乗り物(濃い灰) 5=飲食・買い物(橙) 6=レジャー(青緑)
// =====================================================================
public abstract partial class Q6Art
{
    /// <summary>ピクトグラムの部品。T: c=円(A,B,半径C) r=四角(中心A,B 幅C 高さD 角E) l=太い線(A,B→C,D 太さE) p=多角形 o=輪(A,B 半径C 太さD) t=文字(A,B 大きさC)。Col: 0=絵の色 1=地の色(絵をくりぬく)</summary>
    internal readonly record struct PictoOp(char T, float A, float B, float C, float D, float E, int Col = 0, float[]? P = null, string? S = null);

    internal sealed class PictoB
    {
        public readonly List<PictoOp> Ops = new();
        public void C(float x, float y, float r, int col = 0) => Ops.Add(new('c', x, y, r, 0, 0, col));
        public void R(float x, float y, float w, float h, float rad = 6, int col = 0) => Ops.Add(new('r', x, y, w, h, rad, col));
        public void L(float x0, float y0, float x1, float y1, float w = 26, int col = 0) => Ops.Add(new('l', x0, y0, x1, y1, w, col));
        public void P(int col, params float[] xy) => Ops.Add(new('p', 0, 0, 0, 0, 0, col, xy));
        public void O(float x, float y, float r, float w = 20, int col = 0) => Ops.Add(new('o', x, y, r, w, 0, col));
        public void T(string s, float size, float x = 0, float y = 0, int col = 0) => Ops.Add(new('t', x, y, size, 0, 0, col, null, s));
        public void Arc(float x, float y, float r, float a0, float a1, float w = 22, int col = 0)
        {
            int n = Math.Max(4, (int)(MathF.Abs(a1 - a0) * r / 30f));
            for (int i = 0; i < n; i++) { float b0 = a0 + (a1 - a0) * i / n, b1 = a0 + (a1 - a0) * (i + 1) / n; L(x + MathF.Cos(b0) * r, y + MathF.Sin(b0) * r, x + MathF.Cos(b1) * r, y + MathF.Sin(b1) * r, w, col); }
        }
        public void Heart(float x, float y, float r, int col = 0) => P(col, HeartLocal(x, y, r, false).SelectMany(v => new[] { v.X, v.Y }).ToArray());
        public void Star(float x, float y, float r, int col = 0) => P(col, RegPts(r, 5, -MathF.PI / 2f, .45f).SelectMany(v => new[] { x + v.X, y + v.Y }).ToArray());
        public void Bolt(float x, float y, float s, int col = 0) => P(col, x + 20 * s, y - 100 * s, x - 50 * s, y + 10 * s, x - 5 * s, y + 10 * s, x - 25 * s, y + 100 * s, x + 50 * s, y - 15 * s, x + 5 * s, y - 15 * s);
        public void Drop(float x, float y, float r, int col = 0) { var l = new List<float> { x, y - r * 1.6f }; for (int k = 0; k <= 12; k++) { float b = -.5f + k * (MathF.PI + 1f) / 12f; l.Add(x + MathF.Cos(b) * r); l.Add(y + MathF.Sin(b) * r); } P(col, l.ToArray()); }

        /// <summary>人(人物の図形と同じ姿勢の番号)。s=大きさ(1で高さ約600)。skirt=スカート</summary>
        public void Person(float x, float y, float s, int pose, bool skirt = false, int col = 0)
        {
            var q = Poses[Math.Clamp(pose, 0, Poses.Length - 1)];
            static float Rad(float v) => v * MathF.PI / 180f;
            float ts = MathF.Sin(Rad(q[0])), tc = MathF.Cos(Rad(q[0]));
            var hip = new Vector2(0, 58 + q[9]); var sh = hip + new Vector2(ts * 170f, -tc * 170f); var head = sh + new Vector2(ts * 84f, -tc * 84f);
            Vector2 W(Vector2 v) => new(x + v.X * s, y + v.Y * s);
            void Limb(Vector2 from, float a1, float a2, float l1, float l2, float w)
            {
                var m = from + new Vector2(MathF.Sin(Rad(a1)) * l1, MathF.Cos(Rad(a1)) * l1); var e = m + new Vector2(MathF.Sin(Rad(a2)) * l2, MathF.Cos(Rad(a2)) * l2);
                var a = W(from); var b = W(m); var c = W(e);
                L(a.X, a.Y, b.X, b.Y, w * s, col); L(b.X, b.Y, c.X, c.Y, w * s, col);
            }
            Limb(sh, q[3], q[4], 92, 88, 58);
            Limb(hip, q[7], q[8], 128, 124, 66);
            var h0 = W(hip); var s0 = W(sh); L(h0.X, h0.Y, s0.X, s0.Y, 125 * s, col);
            if (skirt) { var a = W(sh + new Vector2(0, 40)); P(col, a.X - 30 * s, a.Y, a.X + 30 * s, a.Y, a.X + 95 * s, h0.Y + 50 * s, a.X - 95 * s, h0.Y + 50 * s); }
            Limb(hip, q[5], q[6], 128, 124, 66);
            Limb(sh, q[1], q[2], 92, 88, 58);
            var hd = W(head); C(hd.X, hd.Y, 64 * s, col);
        }
        public void Umbrella(float x, float y) { var l = new List<float>(); for (int k = 0; k <= 16; k++) { float a = MathF.PI + k * MathF.PI / 16f; l.Add(x + MathF.Cos(a) * 160); l.Add(y + MathF.Sin(a) * 90); } P(0, l.ToArray()); }
        public void Wheel(float x, float y, float r, int col = 0) { O(x, y, r, 16, col); C(x, y, 10, col); }
        public void Car(float x, float y, float s, int col = 0)
        {
            P(col, x - 150 * s, y + 20 * s, x - 150 * s, y - 30 * s, x - 90 * s, y - 40 * s, x - 55 * s, y - 100 * s, x + 60 * s, y - 100 * s, x + 100 * s, y - 40 * s, x + 150 * s, y - 30 * s, x + 150 * s, y + 20 * s);
            C(x - 90 * s, y + 25 * s, 32 * s, col); C(x + 90 * s, y + 25 * s, 32 * s, col);
        }
    }

