    /// <summary>ピクトグラムの部品の並び(禁止の形は、最後に赤い輪と斜線を重ねる)</summary>
    internal static List<PictoOp> PictoOps(int a)
    {
        var b = new PictoB();
        var it = Pictos[Math.Clamp(a, 0, Pictos.Length - 1)];
        it.Draw(b);
        return b.Ops;
    }
    internal static int PictoStyle(int a) => Pictos[Math.Clamp(a, 0, Pictos.Length - 1)].Style;

    void Picto2D(ArtPen p, float t, Color4 C, Color4 D, Color4 K, Color4 W)
    {
        int style = PictoStyle(a);
        var bg = style == 2 ? W : C;
        float k = 1f + .02f * MathF.Sin(t * 2f);
        p.Zoom(0, 0, k, k, () =>
        {
            p.R(6, 10, 460, 460, 50, p.C(0x000000, .2f));
            p.R(0, 0, 460, 460, 50, bg);
            if (style == 2) p.RL(0, 0, 440, 440, 42, p.C(0xB0B4BA), 6);
            if (style == 3) p.RL(0, 0, 424, 424, 38, D, 14);
            foreach (var o in PictoOps(a))
            {
                var col = o.Col == 0 ? D : bg;
                switch (o.T)
                {
                    case 'c': p.D(o.A, o.B, o.C, col); break;
                    case 'r': p.R(o.A, o.B, o.C, o.D, o.E, col); break;
                    case 'l': p.L(o.A, o.B, o.C, o.D, col, o.E); p.D(o.A, o.B, o.E / 2f, col); p.D(o.C, o.D, o.E / 2f, col); break;
                    case 'p': if (o.P is { Length: >= 6 } xy) p.F(col, xy); break;
                    case 'o': p.Ring(o.A, o.B, o.C, col, o.D); break;
                    case 't': p.T(o.S ?? "", o.C, o.A, o.B, col); break;
                }
            }
            if (style == 2) { p.Ring(0, 0, 190, C, 34); p.L(-134, -134, 134, 134, C, 34); }
        });
    }
